// === Tab: mySketch ===
// Attractor_14.0

let N = 3000 ; let Q = 100 ;
let M = 0.25 ; let W = 0.05 ; ; let K = 0.1 ; let H = 0.01 ; let A = 0.1 ; let S = 0.02 ; let G = 150 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ;
let KX ; let KY ; let L ; let KdX ; let KdY ; let dX ; let dY ; let dZ ;
let I ; let T ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(1112, 834) ; noSmooth() ; background(0) ; stroke(255) ; textSize(20) ;

  X[0] = random(-400, 400) ; Y[0] = 0 ; ; Z[0] = 0 ;
  for ( I = 1 ; I < N ; I++ ){
    X[I] = X[0]*cos(I*2*PI/Q) + random(-20,20) ;
    Y[I] = X[0]*sin(I*2*PI/Q) + random(-20,20) ;
    Z[I] = Z[0] + random(-20,20) ;
  }
  KN = N ;

}// setup()

function draw(){
	let lapse = 0;    // mouse timer
  scale(1.5);
  if ( KN == N ){ fill(0,0,0,10) ; rect(-1,-1, width + 2, height + 2) ; fill(255) ; }
	translate(70, -30);

  for ( I = 0 ; I < KN ; I++ ){
    L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
    KX = L-G ; KY = Z[I] ; T = atan(Y[I]/X[I])*3 ;
    KdY = (M*sin(W*KX)) - (K*W*KX) - (H*KY) + (A*sin(T)) ; 
    KdX = KY ;
    dX = KdX*X[I]/L + (-Y[I]*S) ; dY = KdX*Y[I]/L + (X[I]*S) ; dZ = KdY ;
    NX = X[I] + dX ; NY = Y[I] + dY ; NZ = Z[I] + dZ ;
    stroke(KX*10+50, NY*50+50, KY*100+50);
    line(X[I]-(Y[I]/2)+300,(-Z[I]*10)+(Y[I]/2)+300,NX-(NY/2)+300,(-NZ*10)+(NY/2)+300) ;
    X[I] = NX ; Y[I] = NY ; Z[I] = NZ ;    

  }// I

}// draw()

function mousePressed(){

  background(0) ;

  if ( KN != N ){ 
    KN = N ; 
    for ( I = 1 ; I < N ; I++ ){
      X[I] = (X[0]*cos(I*2*PI/Q)) - (Y[0]*sin(I*2*PI/Q)) + random(-0.1,+0.1) ;
      Y[I] = (X[0]*sin(I*2*PI/Q)) + (Y[0]*cos(I*2*PI/Q)) + random(-0.1,+0.1) ;
      Z[I] = Z[0] + random(-0.1,+0.1) ;
    }
  }else{ KN = 1 ; }

}// mousePressed()

function keyPressed(){
  save('pix.jpg');
}

